test('GET /api/categories/<path> lists products in the category and its subcategories', async () => {
  const res = await fetch(`${base}/api/categories/electronics/audio`)
  assert.equal(res.status, 200)
  const body = await res.json()
  assert.equal(body.path, 'electronics/audio')
  assert.deepEqual(body.products.map((p) => p.sku).sort(), ['HP-200', 'HP-310', 'SPK-10'])
})

test('GET /api/categories/<top-level> includes deeper categories', async () => {
  const res = await fetch(`${base}/api/categories/home`)
  assert.equal(res.status, 200)
  const body = await res.json()
  assert.deepEqual(body.products.map((p) => p.sku).sort(), ['KNF-3', 'PAN-12'])
})

